def get_submission_title(submission):
    """Compute submission title - same logic as Submission.get_title()"""
    survey = submission.survey
    
    # First check if survey has a render_field set
    if survey.render_field:
        # Look for an answer to the render_field question
        render_answer = submission.answers.filter(question=survey.render_field).first()
        if render_answer:
            if render_answer.text_answer:
                return render_answer.text_answer
            elif render_answer.selected_options.exists():
                return ", ".join([opt.text for opt in render_answer.selected_options.all()])
    
    # Fallback: look for questions with title-related keys
    title_question_keys = ["title", "name", "survey_title", "submission_title"]
    
    for answer in submission.answers.all():
        if answer.question.key and answer.question.key.lower() in title_question_keys:
            if answer.text_answer:
                return answer.text_answer
            elif answer.selected_options.exists():
                return ", ".join([opt.text for opt in answer.selected_options.all()])
    
    # Final fallback: return the survey title
    return survey.title


def backfill_computed_titles(apps, schema_editor):
    """Backfill computed_title for all existing submissions."""
    Submission = apps.get_model('survey', 'Submission')
    
    # Get all submissions that don't have a computed_title
    submissions = Submission.objects.filter(computed_title__isnull=True).select_related(
        'survey', 'survey__render_field'
    ).prefetch_related(
        'answers', 'answers__question', 'answers__selected_options'
    )
    
    updated_count = 0
    for submission in submissions.iterator(chunk_size=500):
        computed_title = get_submission_title(submission)
        if computed_title:
            submission.computed_title = computed_title[:500]  # Truncate to max length
            submission.save(update_fields=['computed_title'])
            updated_count += 1
    
    print(f"Updated computed_title for {updated_count} submissions")


